 void CaptureHome(Control c){HomeBase[c]=c.Bounds;BaseFonts[c]=c.Font;foreach(Control child in c.Controls)CaptureHome(child);}
 void ResetHome(){foreach(var pair in HomeBase)if(!pair.Key.IsDisposed){pair.Key.Anchor=AnchorStyles.Top|AnchorStyles.Left;pair.Key.Bounds=pair.Value;pair.Key.Font=BaseFonts[pair.Key];}}
 Dictionary<Control,Rectangle> PageBounds=new Dictionary<Control,Rectangle>();Dictionary<Control,Font> PageFonts=new Dictionary<Control,Font>();Dictionary<Control,bool> PageStretch=new Dictionary<Control,bool>();
 float RenderZoom{get{return Math.Max(.85f,Math.Min(UiZoom,Page.Parent.ClientSize.Width/815f));}}
 void CaptureScale(Control c,Dictionary<Control,Rectangle> bounds,Dictionary<Control,Font> fonts){bounds[c]=c.Bounds;fonts[c]=c.Font;foreach(Control child in c.Controls)if(!(c is FInput))CaptureScale(child,bounds,fonts);}
 void ScaleStored(Control c,float factor,Dictionary<Control,Rectangle> bounds,Dictionary<Control,Font> fonts,bool page){Rectangle r=bounds[c];if(c.Parent==Page&&c is Label)r.Width=Math.Min(r.Width,ContentWidth-r.X-30);if(page&&c.Parent==Page&&PageStretch[c])r.Width=ContentWidth-(c is Card?61:65);c.Anchor=AnchorStyles.Top|AnchorStyles.Left;c.SetBounds((int)(r.X*factor),(int)(r.Y*factor),(int)(r.Width*factor),(int)(r.Height*factor));Font f=fonts[c];c.Font=new Font(f.FontFamily,f.Size*factor,f.Style);var list=c as FList;if(list!=null)list.RowHeight=(int)(38*factor);var input=c as FInput;if(input!=null)input.SetZoom(factor);foreach(Control child in c.Controls)if(!(c is FInput))ScaleStored(child,factor,bounds,fonts,page);}
 void ScaleHome(params Control[] cards){var bounds=new Dictionary<Control,Rectangle>();var fonts=new Dictionary<Control,Font>();foreach(var c in cards)CaptureScale(c,bounds,fonts);Page.SuspendLayout();try{foreach(var c in cards)ScaleStored(c,RenderZoom,bounds,fonts,false);if(HeroBox!=null)HeroBox.PaintZoom=RenderZoom;}finally{Page.ResumeLayout();}}
 void ApplyPageScale(){if(Subtitle.Text=="Главная")return;PageBounds.Clear();PageFonts.Clear();PageStretch.Clear();foreach(Control c in Page.Controls){PageStretch[c]=(c.Anchor&AnchorStyles.Right)!=0||c is Card||c is FList||c is RichTextBox;CaptureScale(c,PageBounds,PageFonts);}RenderPageScale();}
 void RenderPageScale(){if(Subtitle.Text=="Главная"||PageBounds.Count==0)return;Point scroll=Page.AutoScrollPosition;Page.SuspendLayout();try{Page.AutoScrollPosition=Point.Empty;foreach(Control c in Page.Controls)if(PageBounds.ContainsKey(c))ScaleStored(c,RenderZoom,PageBounds,PageFonts,true);}finally{Page.ResumeLayout();Page.AutoScrollPosition=new Point(-scroll.X,-scroll.Y);}}
 RichTextBox ResultsBox(int y,int h){var r=new RoundedTextBox{Bounds=new Rectangle(32,y,ContentWidth-65,h),BackColor=Theme.Card,ForeColor=Theme.Text,BorderStyle=BorderStyle.None,ReadOnly=true,Font=Theme.F(10),DetectUrls=false,WordWrap=true};Page.Controls.Add(r);return r;}
 void ChecksPage(){
