  var list=new FList{Bounds=new Rectangle(32,563,ContentWidth-65,210),Name="check-list"};Page.Controls.Add(list);FillScanList(list);Btn(Page,"Выбрать результат",32,790,240,42,()=>{if(list.SelectedIndex>=0&&list.SelectedIndex<ScanResults.Count)Choose(ScanResults[list.SelectedIndex].Strategy);},true);Btn(Page,"Подробности",285,790,190,42,()=>{if(list.SelectedIndex>=0&&list.SelectedIndex<ScanResults.Count){var r=ScanResults[list.SelectedIndex];TextDialog(r.Strategy,r.Error+"\r\n"+String.Join("\r\n",r.Checks.Select(x=>x.ToString())),false,null);}});Btn(Page,"Последний отчёт",489,790,215,42,()=>{string p=Path.Combine(B.Data,"last-scan.txt");TextDialog("Отчёт подбора",File.Exists(p)?File.ReadAllText(p):"Подбор ещё не выполнялся.",false,null);});
