 void FillScanList(FList list){list.Items.Clear();list.Items.AddRange(ScanResults.Select(x=>x.ToString()));list.SelectedIndex=list.Items.Count>0?0:-1;list.Invalidate();}
 async void StartChecks(bool scan){if(Busy)return;if(B.Preview){Feedback("Предпросмотр","Сетевые операции доступны при запуске в Windows.");return;}if(ExternalTool!=null&&!ExternalTool.HasExited)throw new Exception("Сначала закрой исходный менеджер или тесты.");var output=(RichTextBox)Page.Controls["check-output"];var progress=(Label)Page.Controls["check-progress"];var cancel=(FButton)Page.Controls["check-cancel"];var list=(FList)Page.Controls["check-list"];Busy=true;Scanning=true;ScanCancel=new CancellationTokenSource();cancel.Enabled=true;RefreshExtras();output.Text=scan?"Подбор запущен. Не закрывай программу до восстановления прежней конфигурации.":"Проверяю три HTTPS-адреса…";try{if(scan){ScanResults=await Task.Run(()=>B.ScanStrategies(ScanCancel.Token,(done,total,label)=>UI(()=>{progress.Text=done+" / "+total+" · "+label;SidebarPet.React();})));foreach(var result in ScanResults)SaveStrategyResult(result.Strategy,result.Checks);FillScanList(list);output.Text="Подбор завершён. Прежнее состояние восстановлено. Выбери результат, если хочешь сохранить другую стратегию.";}else{var results=await Task.Run(()=>B.ProbeServices(ScanCancel.Token));output.Text=DateTime.Now+"\r\n"+String.Join("\r\n\r\n",results.Select(x=>x.ToString()))+"\r\n\r\nГолос, видео и вход в аккаунт: автоматически не проверены.";Backend.Atomic(Path.Combine(B.Data,"last-check.txt"),output.Text);RecordChecks(results);}progress.Text="Готово";Feedback("Проверка завершена",scan?"Прежний режим работы восстановлен.":"Результаты доступны на этой странице.");}catch(OperationCanceledException){progress.Text="Отменено";output.AppendText(scan?"\nПодбор отменён. Прежнее состояние восстановлено. Частичный отчёт сохранён.":"\nПроверка отменена.");}catch(Exception ex){progress.Text="Не завершено — см. ошибку";Error(ex);}finally{ScanCancel.Dispose();ScanCancel=null;Busy=false;Scanning=false;cancel.Enabled=false;RefreshState();}}
 public void PreviewExtras(int stage){
  noticeUntil=0;Notice.Visible=false;
  if(stage==0){Navigate("Настройки");Page.AutoScrollPosition=new Point(0,600);}
  if(stage==1){foreach(var card in Page.Controls.OfType<Card>())foreach(var toggle in card.Controls.OfType<FToggle>())toggle.Checked=!toggle.Checked;Page.AutoScrollPosition=Point.Empty;}
  if(stage==2)Page.AutoScrollPosition=new Point(0,600);
  if(stage==3){UiZoom=1.5f;Theme.Orange=AccentColor("purple");Location=Point.Empty;Size=new Size(1920,1080);Navigate("Настройки");}
  if(stage==4)Page.AutoScrollPosition=new Point(0,1200);
  if(stage==5)Navigate("Главная");
  if(stage==6){Size=new Size(1190,820);Navigate("Проверки");}
 }
